t.script:
(function () {
  function $(id){ return document.getElementById(id); }

  function buildCanvas() {
    const stage = $('spw_canvas');
    const base  = $('spw_product_img');
    const logo  = $('spw_logo_preview');
    if (!stage || !base) return null;

    const dpr = window.devicePixelRatio || 1;
    const stageRect = stage.getBoundingClientRect();
    const baseRect  = base.getBoundingClientRect();

    const canvas = document.createElement('canvas');
    canvas.width  = Math.max(1, Math.round(stageRect.width * dpr));
    canvas.height = Math.max(1, Math.round(stageRect.height * dpr));
    const ctx = canvas.getContext('2d');
    ctx.scale(dpr, dpr);

    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, stageRect.width, stageRect.height);

    const bx = baseRect.left - stageRect.left;
    const by = baseRect.top  - stageRect.top;
    ctx.drawImage(base, bx, by, baseRect.width, baseRect.height);

    if (logo && !logo.classList.contains('d-none') && logo.src) {
      const lr = logo.getBoundingClientRect();
      const cx = (lr.left - stageRect.left) + lr.width/2;
      const cy = (lr.top  - stageRect.top ) + lr.height/2;
      const rotDeg = parseFloat(($('spw_rotation') && $('spw_rotation').value) || 0);
      const rad = rotDeg * Math.PI / 180;
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(rad);
      ctx.drawImage(logo, -lr.width/2, -lr.height/2, lr.width, lr.height);
      ctx.restore();
    }
    return canvas;
  }

  window.spwDownloadPNG = function () {
    try {
      const canvas = buildCanvas();
      if (!canvas) return;
      const url = canvas.toDataURL('image/png');
      const a = document.createElement('a');
      a.href = url;
      a.download = 'personalizacion.png';
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch (e) {
      console.error('spwDownloadPNG error', e);
      alert('No se pudo generar el PNG.');
    }
  };

  window.spwAddToCart = async function () {
    try {
      const canvas = buildCanvas();
      if (!canvas) return;
      const dataUrl = canvas.toDataURL('image/png');
      const png_b64 = dataUrl.split(',')[1] || '';

      const variantId = $('spw_variant_id') && $('spw_variant_id').value;
      const qty       = parseInt(($('spw_qty') && $('spw_qty').value) || '1', 10);

      const techEl = document.querySelector('input[name="spw_tech"]:checked');
      const svgEl  = document.querySelector('input[name="spw_svg_color"]:checked');
      const tech = techEl ? techEl.value : '';
      const svg_color = svgEl ? svgEl.value : '';
      const notes = ($('spw_notes') && $('spw_notes').value) || '';

      const payload = {
        variant_id: parseInt(variantId || '0', 10),
        qty: isNaN(qty) || qty < 1 ? 1 : qty,
        tech: tech,
        svg_color: svg_color,
        notes: notes,
        png_b64: png_b64,
      };

      const resp = await fetch('/spw/add_to_cart', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload),
        credentials: 'same-origin',
      });
      const res = await resp.json();
      if (res && res.ok) {
        window.location.href = res.cart_url || '/shop/cart';
      } else {
        alert((res && res.message) || 'No se pudo añadir al carrito.');
      }
    } catch (e) {
      console.error('spwAddToCart error', e);
      alert('No se pudo añadir al carrito.');
    }
  };
})();
